def merge_intervals(intervals):
    if not intervals:
        return []
    sorted_intervals = sorted(intervals, key=lambda x: x[0])
    merged = [list(sorted_intervals[0])]
    for start, end in sorted_intervals[1:]:
        last = merged[-1]
        if start <= last[1] + 1:
            last[1] = max(last[1], end)
        else:
            merged.append([start, end])
    return merged

import heapq


def toposort(nodes, edges):
    adj = {n: set() for n in nodes}
    indeg = {n: 0 for n in nodes}

    for src, dst in edges:
        if src in adj and dst in adj:
            if dst not in adj[src]:
                adj[src].add(dst)
                indeg[dst] += 1

    heap = [n for n in nodes if indeg[n] == 0]
    heapq.heapify(heap)

    order = []
    while heap:
        node = heapq.heappop(heap)
        order.append(node)
        for nxt in adj[node]:
            indeg[nxt] -= 1
            if indeg[nxt] == 0:
                heapq.heappush(heap, nxt)

    if len(order) != len(nodes):
        raise ValueError("Graph contains a cycle")

    return order

def stable_batches(items, limit):
    if limit <= 0:
        raise ValueError
    for _, weight in items:
        if weight <= 0 or weight > limit:
            raise ValueError
    batches = []
    current = []
    current_weight = 0
    for name, weight in items:
        if current and current_weight + weight > limit:
            batches.append(current)
            current = []
            current_weight = 0
        current.append(name)
        current_weight += weight
    if current:
        batches.append(current)
    return batches

import re

_ENV_KEY_RE = re.compile(r'[A-Za-z_][A-Za-z0-9_]*')


def _strip_quotes(value):
    if len(value) >= 2 and value[0] == value[-1] and value[0] in ('"', "'"):
        return value[1:-1]
    return value


def parse_env(text):
    result = {}
    for raw_line in text.splitlines():
        line = raw_line.strip()
        if not line or line.startswith('#'):
            continue
        idx = line.find('=')
        if idx == -1:
            raise ValueError(f'Invalid environment assignment (no "="): {raw_line!r}')
        key = line[:idx].strip()
        value = line[idx + 1:].strip()
        if not _ENV_KEY_RE.fullmatch(key):
            raise ValueError(f'Invalid environment key: {key!r}')
        result[key] = _strip_quotes(value)
    return result

import math


def retry_delay(attempt, base, cap):
    if attempt < 0:
        raise ValueError("attempt must be a nonnegative integer")
    if base < 0:
        raise ValueError("base must be a nonnegative number")
    if cap < 0:
        raise ValueError("cap must be a nonnegative number")

    # Any zero makes base * 2**attempt == 0, and min(0, cap>=0) == 0.
    if base == 0.0 or cap == 0.0:
        return 0.0

    # base > 0 and cap > 0.
    # base * 2**attempt >= cap  <=>  attempt >= log2(cap) - log2(base).
    # Splitting log2(cap/base) into log2(cap) - log2(base) avoids
    # cap/base overflowing to inf, keeping the threshold finite
    # (within roughly [-1074, 2098] for finite nonnegative floats).
    threshold = math.log2(cap) - math.log2(base)

    if attempt >= threshold:
        # The true product is >= cap (attempt is a nonnegative integer and
        # threshold is finite), so we never form 2**attempt explicitly.
        return float(cap)

    # attempt < threshold guarantees base * 2**attempt < cap <= max float,
    # so the exact result is a finite float. math.ldexp(base, attempt)
    # applies the binary exponent directly and does not build a huge int.
    value = math.ldexp(base, attempt)
    return float(min(cap, value))

def fifo_admit(active, queued, budget, slots):
    if any(reservation > budget for reservation in queued):
        raise ValueError("queued reservation exceeds the whole budget")

    remaining_tokens = budget - sum(active)
    remaining_slots = slots - len(active)

    admitted = []
    for reservation in queued:
        if reservation <= remaining_tokens and remaining_slots > 0:
            admitted.append(reservation)
            remaining_tokens -= reservation
            remaining_slots -= 1
        else:
            break

    remaining = list(queued[len(admitted):])
    return admitted, remaining
